_install('ngt', '"""Bounded nonlinear Gaussian tied tree (srhm.tex section 8, Theorem ngt) and its pure learner.\n\nModel:  z_root ~ stationary law;  children z_{wi} = phi_i(z_w) + psi * eps,  i = 1..S,  same phi at every\n        height;  phi_i(z) = theta_i . basis(sigma(z)),  sigma(z) = z / (1 + |z|);  leaves observed.\nLearner: maximum likelihood by EM, zero labels.  Beliefs are exact on a grid; the cell is sum-product.\n        E-step = one upward + one downward BP pass.  The M-step uses only sums over grids of grid-local\n        expected statistics (Fisher identity): weighted least squares for theta_i, closed form for psi.\n"""\nimport numpy as np\n\nS = 3\nG = np.linspace(-4.0, 4.0, 161)                  # latent grid (same type as the leaves)\nNB = 5\n\n\ndef sig(z):\n    return z / (1.0 + np.abs(z))\n\n\ndef basis(z):\n    p = sig(z)\n    return np.stack([np.ones_like(p), p, p ** 2, p ** 3, np.tanh(3 * p)], -1)\n\n\nBG = basis(G)                                     # (n, NB)\n\n\nclass Kernel:\n    def __init__(self, theta, psi):\n        self.theta = np.asarray(theta, float)     # (S, NB)\n        self.psi = float(psi)\n\n    def phi(self, z):\n        return basis(z) @ self.theta.T            # (..., S)\n\n    def T(self):\n        """Grid transition matrices T_i[g, g\'] = P(child_i = G[g\'] | parent = G[g])."""\n        m = BG @ self.theta.T                     # (n, S)\n        out = []\n        for i in range(S):\n            t = np.exp(-(G[None, :] - m[:, i:i + 1]) ** 2 / (2 * self.psi ** 2))\n            out.append(t / t.sum(1, keepdims=True))\n        return out\n\n    def stationary(self, T=None, iters=400):\n        T = self.T() if T is None else T\n        mu = np.ones(len(G)) / len(G)\n        for _ in range(iters):\n            mu = sum(mu @ t for t in T) / S\n        mu = mu + 1e-15\n        return mu / mu.sum()\n\n\ndef random_true_kernel(rng, psi=0.35):\n    th = np.zeros((S, NB))\n    for i in range(S):\n        b = rng.uniform(0.6, 1.4) * rng.choice([-1, 1])\n        th[i, 0] = rng.uniform(-0.3, 0.3)\n        th[i, 1] = b\n        th[i, 4] = rng.uniform(-1, 1) * abs(b) / 3 * 0.9\n    return Kernel(th, psi)\n\n\ndef sample_trees(ker, U, L, rng, burn=40):\n    z = np.zeros(U)\n    for _ in range(burn):                         # root from the stationary law\n        i = rng.integers(S, size=U)\n        z = ker.phi(z)[np.arange(U), i] + ker.psi * rng.normal(size=U)\n    root = z.copy()\n    z = z[:, None]\n    for _ in range(L):\n        m = ker.phi(z)                            # (U, nodes, S)\n        z = (m + ker.psi * rng.normal(size=m.shape)).reshape(U, -1)\n    return z, root\n\n\ndef _leaf_msgs(ker, Xc):\n    """Xc (N, S) leaf children of height-1 nodes -> messages (N, S, n) with log scales (N,)."""\n    m = BG @ ker.theta.T                                           # (n, S)\n    lm = -(Xc[:, :, None] - m.T[None]) ** 2 / (2 * ker.psi ** 2) - np.log(np.sqrt(2 * np.pi) * ker.psi)\n    mx = lm.max(2, keepdims=True)\n    return np.exp(lm - mx), mx[..., 0].sum(1)\n\n\ndef upward(ker, X, T):\n    """Returns per-height lists: msgs[h] (N_h, S, n) messages from children, up[h] (N_h, n) normalised\n    beliefs, and the total log-likelihood contribution of the upward normalisers."""\n    U, nl = X.shape\n    L = int(round(np.log(nl) / np.log(S)))\n    msgs, ups, ll = {}, {}, 0.0\n    m, lsc = _leaf_msgs(ker, X.reshape(-1, S))\n    ll += lsc.sum()\n    for h in range(1, L + 1):\n        if h > 1:\n            uc = ups[h - 1].reshape(-1, S, len(G))                 # children beliefs\n            m = np.stack([uc[:, i] @ T[i].T for i in range(S)], 1)\n            mx = m.max(2, keepdims=True); m = m / mx; ll += np.log(mx).sum()\n        b = m.prod(1) + 1e-300                                    # underflow floor\n        z = b.sum(1, keepdims=True)\n        ll += np.log(z).sum()\n        msgs[h], ups[h] = m, b / z\n    return msgs, ups, ll, L\n\n\ndef estep(ker, X):\n    """Sufficient statistics for the M-step, summed over all grids of all trees (tied kernel)."""\n    T = ker.T()\n    pi = ker.stationary(T)\n    msgs, ups, ll, L = upward(ker, X, T)\n    ll += np.log(ups[L] @ pi).sum()\n    n = len(G)\n    W = np.zeros((S, n)); Y = np.zeros((S, n)); Y2 = np.zeros((S, n))\n    o = np.tile(pi, (ups[L].shape[0], 1))                          # outside messages at height L\n    Xc = X.reshape(-1, S)\n    for h in range(L, 0, -1):\n        m = msgs[h]\n        o_child = np.zeros((m.shape[0], S, n))\n        for i in range(S):\n            others = np.prod(np.delete(m, i, axis=1), axis=1)\n            r = o * others + 1e-300                                # underflow floor\n            r /= r.sum(1, keepdims=True)\n            if h > 1:\n                uc = ups[h - 1].reshape(-1, S, n)[:, i]\n                Z = (r * (uc @ T[i].T)).sum(1, keepdims=True)         # raw (unscaled) message\n                pair = T[i] * ((r / Z).T @ uc)                     # sum_w p_w(g, g\')\n                W[i] += pair.sum(1); Y[i] += pair @ G; Y2[i] += pair @ G ** 2\n                oc = r @ T[i]\n                o_child[:, i] = oc / oc.sum(1, keepdims=True)\n            else:\n                P = r * m[:, i]; P /= P.sum(1, keepdims=True)\n                x = Xc[:, i]\n                W[i] += P.sum(0); Y[i] += P.T @ x; Y2[i] += P.T @ x ** 2\n        o = o_child.reshape(-1, n)\n    return W, Y, Y2, ll\n\n\ndef mstep(W, Y, Y2):\n    th = np.zeros((S, NB)); sse = 0.0\n    for i in range(S):\n        A = BG.T @ (W[i][:, None] * BG) + 1e-9 * np.eye(NB)\n        th[i] = np.linalg.solve(A, BG.T @ Y[i])\n        f = BG @ th[i]\n        sse += (Y2[i] - 2 * f * Y[i] + f ** 2 * W[i]).sum()\n    return Kernel(th, np.sqrt(max(sse / W.sum(), 1e-4)))\n\n\ndef random_init(rng):\n    th = np.zeros((S, NB))\n    th[:, 0] = rng.normal(0, 0.2, S)\n    th[:, 1] = rng.uniform(0.3, 1.2, S) * rng.choice([-1, 1], S)\n    th[:, 2:] = rng.normal(0, 0.1, (S, NB - 2))\n    return Kernel(th, 0.8)\n\n\ndef fit(X, rng, restarts=6, iters=300, tol=1e-7):\n    best = None\n    for _ in range(restarts):\n        ker, prev = random_init(rng), -np.inf\n        for it in range(iters):\n            W, Y, Y2, ll = estep(ker, X)\n            ker = mstep(W, Y, Y2)\n            if ll - prev < tol * abs(ll):\n                break\n            prev = ll\n        ll = estep(ker, X)[3]\n        if best is None or ll > best[0]:\n            best = (ll, ker)\n    return best[1], best[0]\n\n\ndef root_posterior_mean(ker, X, chunk=40):\n    T = ker.T(); pi = ker.stationary(T)\n    out = []\n    for a in range(0, X.shape[0], chunk):             # chunked: memory, not results\n        _, ups, _, L = upward(ker, X[a:a + chunk], T)\n        P = ups[L] * pi\n        out.append((P / P.sum(1, keepdims=True)) @ G)\n    return np.concatenate(out)\n\n\ndef kernel_error(ker, true):\n    """RMS over the true stationary law of |phi_hat - phi|, averaged over positions, relative to psi."""\n    pi = true.stationary()\n    d = (BG @ ker.theta.T - BG @ true.theta.T) ** 2              # (n, S)\n    return float(np.sqrt((pi[:, None] * d).sum(0)).mean() / true.psi), abs(ker.psi / true.psi - 1)\n')
_install('codebook', '"""Tied codebook tree (srhm.tex Definition codebook, section 8.7): exact beliefs over v symbols.\n\nModel: every node (leaves included) carries a symbol a in {0..v-1}; symbol a has a value c_a in leaf\ncoordinates (R^d).  Children\'s symbols a\'_i ~ M_i[:, a] independently, the SAME M_i at every height,\nthe leaf level included (tied).  A leaf is x = c_{a\'} + tau * eps.  Root symbol ~ stationary law of\nthe average kernel.\nLearner: maximum likelihood by exact EM, zero labels.  E-step = one upward + one downward sum-product\npass; the M-step uses only sums over grids of grid-local expected statistics (pair counts for M_i,\nweighted means for c and tau).  Root prediction E[c_root | leaves] needs no labels: the codebook\ncarries the naming.\n"""\nimport numpy as np\n\nS = 3\nFLOOR = 1e-300\n\n\nclass Codebook:\n    def __init__(self, M, c, tau):\n        self.M = np.asarray(M, float)        # (S, v, v): M[i, a\', a] = P(child_i = a\' | parent = a)\n        self.c = np.asarray(c, float)        # (v, d)\n        self.tau = float(tau)\n\n    @property\n    def v(self):\n        return self.c.shape[0]\n\n    def stationary(self, iters=500):\n        Mb = self.M.mean(0)\n        mu = np.ones(self.v) / self.v\n        for _ in range(iters):\n            mu = Mb @ mu\n        mu = mu + 1e-15\n        return mu / mu.sum()\n\n\ndef _emission(cb, X):\n    """X (N, d) leaves -> normalised likelihood over leaf symbols (N, v) and total log scale."""\n    d = X.shape[1]\n    lq = -((X[:, None, :] - cb.c[None]) ** 2).sum(-1) / (2 * cb.tau ** 2) \\\n         - d * np.log(np.sqrt(2 * np.pi) * cb.tau)\n    mx = lq.max(1, keepdims=True)\n    u = np.exp(lq - mx)\n    z = u.sum(1, keepdims=True)\n    return u / z, (mx + np.log(z)).sum()\n\n\ndef _leaves(X):\n    X = np.asarray(X, float)\n    return X[..., None] if X.ndim == 2 else X            # (U, n_leaves, d)\n\n\ndef upward(cb, X):\n    X = _leaves(X)\n    U, nl, d = X.shape\n    L = int(round(np.log(nl) / np.log(S)))\n    u, ll = _emission(cb, X.reshape(-1, d))\n    ups, msgs = {0: u}, {}\n    for h in range(1, L + 1):\n        uc = ups[h - 1].reshape(-1, S, cb.v)\n        m = np.stack([uc[:, i] @ cb.M[i] for i in range(S)], 1)      # m[:, i, a] = sum_a\' u(a\') M_i[a\', a]\n        mx = m.max(2, keepdims=True); m = m / mx; ll += np.log(mx).sum()\n        b = m.prod(1) + FLOOR\n        z = b.sum(1, keepdims=True); ll += np.log(z).sum()\n        msgs[h], ups[h] = m, b / z\n    return ups, msgs, ll, L, X.reshape(-1, d)\n\n\ndef estep(cb, X):\n    pi = cb.stationary()\n    ups, msgs, ll, L, Xf = upward(cb, X)\n    ll += np.log(ups[L] @ pi).sum()\n    v = cb.v\n    pair = np.zeros((S, v, v))                              # pair[i, a, a\'] summed over all grids\n    o = np.tile(pi, (ups[L].shape[0], 1))\n    for h in range(L, 0, -1):\n        m = msgs[h]\n        uc = ups[h - 1].reshape(-1, S, v)\n        o_child = np.zeros((m.shape[0], S, v))\n        for i in range(S):\n            r = o * np.prod(np.delete(m, i, axis=1), axis=1) + FLOOR\n            r /= r.sum(1, keepdims=True)\n            Z = (r * (uc[:, i] @ cb.M[i])).sum(1, keepdims=True)    # raw (unscaled) message\n            pair[i] += cb.M[i].T * ((r / Z).T @ uc[:, i])\n            oc = r @ cb.M[i].T\n            o_child[:, i] = oc / oc.sum(1, keepdims=True)\n        o = o_child.reshape(-1, v)\n    P = o * ups[0]                                          # leaf-symbol posteriors (n_leaves, v)\n    P /= P.sum(1, keepdims=True)\n    return pair, P, Xf, ll\n\n\ndef mstep(pair, P, Xf, smooth=1e-6):\n    M = np.stack([((pair[i] + smooth) / (pair[i] + smooth).sum(1, keepdims=True)).T for i in range(S)])\n    w = P.sum(0) + 1e-12\n    c = (P.T @ Xf) / w[:, None]\n    sse = (P * ((Xf[:, None, :] - c[None]) ** 2).sum(-1)).sum()\n    tau = np.sqrt(max(sse / (Xf.shape[0] * Xf.shape[1]), 1e-6))\n    return Codebook(M, c, tau)\n\n\ndef random_init(X, v, rng):\n    Xf = _leaves(X).reshape(-1, _leaves(X).shape[-1])\n    qs = np.quantile(Xf, (np.arange(v) + 0.5) / v, axis=0)\n    c = qs + 0.05 * Xf.std(0) * rng.normal(size=qs.shape)\n    M = rng.dirichlet(np.ones(v), size=(S, v)).transpose(0, 2, 1)   # columns = distributions\n    return Codebook(M, c, 0.5 * Xf.std() / v ** (1 / Xf.shape[1]) + 0.1)\n\n\ndef fit(X, v, rng, restarts=4, iters=250, tol=1e-7):\n    best = None\n    for _ in range(restarts):\n        cb, prev = random_init(X, v, rng), -np.inf\n        for _ in range(iters):\n            pair, P, Xf, ll = estep(cb, X)\n            cb = mstep(pair, P, Xf)\n            if ll - prev < tol * abs(ll):\n                break\n            prev = ll\n        ll = estep(cb, X)[3]\n        if best is None or ll > best[0]:\n            best = (ll, cb)\n    return best[1], best[0]\n\n\ndef root_value(cb, X, chunk=40):\n    X = _leaves(X)\n    pi = cb.stationary(); out = []\n    for a in range(0, X.shape[0], chunk):\n        ups, _, _, L, _ = upward(cb, X[a:a + chunk])\n        p = ups[L] * pi\n        out.append((p / p.sum(1, keepdims=True)) @ cb.c)\n    return np.concatenate(out)[:, 0] if X.shape[-1] == 1 else np.concatenate(out)\n')
"""V1' (srhm.tex section 8.7): tied codebook tree on the V1 data (bounded nonlinear Gaussian trees).

Codebook sizes v in {4, 8, 16, 32}; training data (U trees of depth L):
  (1,7) N1=729, (1,8) N1=2187, (3,8) N1=6561, (9,8) N1=19683,    and at N1=6561 the shallow splits
  (81,5), (243,4) to test packaging and depth extrapolation (Q2, Q3).
Always tested on 400 depth-8 trees: root R^2 of E[c_root | leaves] against the Bayes oracle.  Zero labels.
"""
import os, sys, json, time
os.environ.setdefault("OMP_NUM_THREADS", "2")
import numpy as np
from multiprocessing import Pool
import ngt, codebook as cbm

OUT = os.path.join(os.path.dirname(os.path.abspath(globals().get("__file__", "./x"))), "exp_codebook_results.jsonl")
DATA = [(1, 7), (1, 8), (3, 8), (9, 8), (81, 5), (243, 4)]


def job(args):
    kseed, v, U, L, seed = args
    true = ngt.random_true_kernel(np.random.default_rng(100 + kseed))
    X, _ = ngt.sample_trees(true, U, L, np.random.default_rng(1000 * kseed + seed))
    t = time.time()
    cb, ll = cbm.fit(X, v, np.random.default_rng(seed))
    Xt, rt = ngt.sample_trees(true, 400, 8, np.random.default_rng(7))
    r2 = lambda p: float(1 - ((p - rt) ** 2).mean() / rt.var())
    return dict(kernel=kseed, v=v, U=U, L=L, N1=U * 3 ** (L - 1), seed=seed, labels=0,
                n_params=3 * v * (v - 1) + v + 1, r2=round(r2(cbm.root_value(cb, Xt)), 4),
                r2_oracle=round(r2(ngt.root_posterior_mean(true, Xt)), 4), tau=round(cb.tau, 4),
                ll_per_leaf=round(ll / X.size, 4), secs=round(time.time() - t, 1))


if __name__ == "__main__":
    jobs = [(k, v, U, L, s) for (U, L) in DATA for v in (32, 16, 8, 4) for k in (0, 1) for s in range(2)]
    jobs.sort(key=lambda j: -j[2] * 3 ** (j[3] - 1) * j[1] ** 2)          # largest first
    on_colab = "BUDGET_SECONDS" in os.environ
    workers = int(os.environ.get("WORKERS", max(1, os.cpu_count() - 1) if on_colab else 3))
    print(json.dumps(dict(event="start", workers=workers, jobs=len(jobs))), flush=True)
    open(OUT, "w").close()
    with Pool(workers) as pool:
        for rec in pool.imap_unordered(job, jobs):
            print(json.dumps(rec), flush=True)
            with open(OUT, "a") as fh:
                fh.write(json.dumps(rec) + "\n")
